async fn v2_western_electional_starting_journey_search() {
    let body: types::StartingJourneyElectionSearchRequest =
        serde_json::from_str(r#"{"search_window": {"end": "x", "start": "x"}}"#).unwrap();
    contract("v2_western_electional_starting_journey_search", |client| {
        let body = body.clone();
        async move {
            client
                .western()
                .electional()
                .starting_journey_search(&body)
                .await
        }
    })
    .await;
}

